{"id":"5ed0189b-401f-472d-b8c6-54ecd3c4e9ee","inserted_at":"2026-07-03T22:31:15.2661+00:00","updated_at":"2026-07-03T22:31:15.2661+00:00","type":"sql","name":"Untitled query","description":"","content":{"sql":"-- =========================================================================\r\n-- MEDAGLIERE SPARTANO (Traccia Impegno & Traccia Impatto)\r\n-- =========================================================================\r\n\r\n-- 1. Tabella dei Badge Sbloccati\r\nCREATE TABLE IF NOT EXISTS user_badges (\r\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\r\n    badge_type TEXT NOT NULL,\r\n    earned_at TIMESTAMPTZ DEFAULT now(),\r\n    UNIQUE(user_id, badge_type) -- Un utente può avere un solo badge per tipo\r\n);\r\n\r\n-- Abilitiamo RLS\r\nALTER TABLE user_badges ENABLE ROW LEVEL SECURITY;\r\nCREATE POLICY \"Users can read own badges\" \r\nON user_badges FOR SELECT \r\nUSING (auth.uid() = user_id);\r\n\r\n-- 2. Trigger per Traccia Impegno (Al numero di segnalazioni effettuate)\r\nCREATE OR REPLACE FUNCTION award_action_badges()\r\nRETURNS TRIGGER AS $$\r\nDECLARE\r\n    total_reports INT;\r\n    badge_to_award TEXT;\r\n    bonus_points INT;\r\nBEGIN\r\n    -- Conta le segnalazioni totali di questo utente\r\n    SELECT COUNT(*) INTO total_reports \r\n    FROM civic_reports \r\n    WHERE user_id = NEW.user_id;\r\n\r\n    badge_to_award := NULL;\r\n    bonus_points := 0;\r\n\r\n    IF total_reports = 1 THEN\r\n        badge_to_award := 'sentinella';\r\n        bonus_points := 50;\r\n    ELSIF total_reports = 5 THEN\r\n        badge_to_award := 'esploratore';\r\n        bonus_points := 100;\r\n    ELSIF total_reports = 10 THEN\r\n        badge_to_award := 'spartano';\r\n        bonus_points := 200;\r\n    ELSIF total_reports = 25 THEN\r\n        badge_to_award := 'faro';\r\n        bonus_points := 500;\r\n    ELSIF total_reports = 50 THEN\r\n        badge_to_award := 'custode';\r\n        bonus_points := 1000;\r\n    END IF;\r\n\r\n    -- Se c'è un badge da assegnare, proviamo a inserirlo\r\n    IF badge_to_award IS NOT NULL THEN\r\n        BEGIN\r\n            INSERT INTO user_badges (user_id, badge_type) \r\n            VALUES (NEW.user_id, badge_to_award);\r\n            \r\n            -- Se l'inserimento ha successo, aggiungiamo i punti PTI\r\n            UPDATE profiles \r\n            SET total_tokens = COALESCE(total_tokens, 0) + bonus_points \r\n            WHERE id = NEW.user_id;\r\n        EXCEPTION WHEN unique_violation THEN\r\n            -- L'utente ha già questo badge, non facciamo nulla\r\n        END;\r\n    END IF;\r\n\r\n    RETURN NEW;\r\nEND;\r\n$$ LANGUAGE plpgsql;\r\n\r\n-- Trigger dopo l'INSERT di una nuova segnalazione (Traccia A)\r\nDROP TRIGGER IF EXISTS trigger_award_action_badges ON civic_reports;\r\nCREATE TRIGGER trigger_award_action_badges\r\n    AFTER INSERT ON civic_reports\r\n    FOR EACH ROW\r\n    EXECUTE FUNCTION award_action_badges();\r\n\r\n-- 3. Trigger per Traccia Impatto (Al cambio di status in confirmed/resolved)\r\nCREATE OR REPLACE FUNCTION award_impact_badges()\r\nRETURNS TRIGGER AS $$\r\nDECLARE\r\n    total_confirmed INT;\r\n    total_resolved INT;\r\n    badge_to_award TEXT;\r\n    bonus_points INT;\r\nBEGIN\r\n    -- Se lo status non è cambiato in qualcosa di positivo, esci\r\n    IF NEW.status = OLD.status OR NEW.status NOT IN ('confirmed', 'verified', 'resolved') THEN\r\n        RETURN NEW;\r\n    END IF;\r\n\r\n    badge_to_award := NULL;\r\n    bonus_points := 0;\r\n\r\n    -- Conta confermati\r\n    SELECT COUNT(*) INTO total_confirmed \r\n    FROM civic_reports \r\n    WHERE user_id = NEW.user_id AND status IN ('confirmed', 'verified', 'resolved');\r\n    \r\n    -- Conta risolti\r\n    SELECT COUNT(*) INTO total_resolved \r\n    FROM civic_reports \r\n    WHERE user_id = NEW.user_id AND status = 'resolved';\r\n\r\n    IF total_confirmed = 1 AND NEW.status = 'confirmed' THEN\r\n        badge_to_award := 'eco';\r\n        bonus_points := 25;\r\n    END IF;\r\n\r\n    IF total_resolved = 1 AND NEW.status = 'resolved' THEN\r\n        badge_to_award := 'forgiatore';\r\n        bonus_points := 100;\r\n    ELSIF total_resolved = 5 AND NEW.status = 'resolved' THEN\r\n        badge_to_award := 'eroe';\r\n        bonus_points := 500;\r\n    END IF;\r\n\r\n    -- Se c'è un badge da assegnare, proviamo a inserirlo\r\n    IF badge_to_award IS NOT NULL THEN\r\n        BEGIN\r\n            INSERT INTO user_badges (user_id, badge_type) \r\n            VALUES (NEW.user_id, badge_to_award);\r\n            \r\n            UPDATE profiles \r\n            SET total_tokens = COALESCE(total_tokens, 0) + bonus_points \r\n            WHERE id = NEW.user_id;\r\n        EXCEPTION WHEN unique_violation THEN\r\n            -- Già posseduto\r\n        END;\r\n    END IF;\r\n\r\n    RETURN NEW;\r\nEND;\r\n$$ LANGUAGE plpgsql;\r\n\r\n-- Trigger dopo l'UPDATE di una segnalazione (Traccia B)\r\nDROP TRIGGER IF EXISTS trigger_award_impact_badges ON civic_reports;\r\nCREATE TRIGGER trigger_award_impact_badges\r\n    AFTER UPDATE ON civic_reports\r\n    FOR EACH ROW\r\n    EXECUTE FUNCTION award_impact_badges();","content_id":"5ed0189b-401f-472d-b8c6-54ecd3c4e9ee","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
